import{bQ as e,aL as r,u as t,G as a}from"./chunks/framework.DaEK0KQB.js";const u=JSON.parse('{"title":"Cloudflare的Workers+D1","description":"","frontmatter":{"title":"Cloudflare的Workers+D1","date":"2026-04-12T20:03:43.000Z","permalink":"/pages/855422/","categories":["更多","服务器实例"],"tags":[null]},"headers":[],"relativePath":"更多/服务器实例/02.Cloudflare的Workers+D1.md","filePath":"更多/服务器实例/02.Cloudflare的Workers+D1.md","lastUpdated":1786944735000}'),d={name:"更多/服务器实例/02.Cloudflare的Workers+D1.md"};function n(s,o,l,i,c,g){return r(),t("div",null,[...o[0]||(o[0]=[a('<h1 id="使用cf爬取第三方新闻内容" tabindex="-1">使用cf爬取第三方新闻内容 <a class="header-anchor" href="#使用cf爬取第三方新闻内容" aria-label="Permalink to &quot;使用cf爬取第三方新闻内容&quot;">​</a></h1><h2 id="一、需求" tabindex="-1">一、需求 <a class="header-anchor" href="#一、需求" aria-label="Permalink to &quot;一、需求&quot;">​</a></h2><h3 id="_1-1-背景" tabindex="-1">1.1 背景 <a class="header-anchor" href="#_1-1-背景" aria-label="Permalink to &quot;1.1 背景&quot;">​</a></h3><p>上游提供新闻类 HTTP API（示例基址：<code>http://api.didaliveshow.com/article</code>），列表与详情分开展示。若每次由客户端直接请求上游，会遇到几类问题：<strong>接口稳定性与速率不可控</strong>、<strong>列表与详情字段分散不利于产品侧统一消费</strong>、以及<strong>无法在本地做分页缓存与统计</strong>。</p><p>因此需要一层「同步服务」：定期或按需把数据拉取到自己的存储里，再由自有接口对外提供稳定、可预期的 JSON。</p><h3 id="_1-2-目标-功能" tabindex="-1">1.2 目标（功能） <a class="header-anchor" href="#_1-2-目标-功能" aria-label="Permalink to &quot;1.2 目标（功能）&quot;">​</a></h3><ul><li><strong>全量列表入库</strong>：把上游所有列表页扫完，至少落库每条新闻的 id 及列表中已有的元数据（标题、缩略图、时间等），<strong>先不写正文</strong>，以降低单次任务压力。</li><li><strong>详情补全</strong>：在列表阶段完成后，按<strong>文章 id 有序</strong>批量拉取详情，写入正文等字段，并标记「已同步详情」。</li><li><strong>断点续跑</strong>：列表阶段不能假设一次 Worker 执行能跑完所有页（执行时间、子请求数均有限制），需要<strong>持久化游标</strong>，支持多次调用接续进度。</li><li><strong>只读对外接口</strong>：提供分页列表、单篇详情等 <strong>GET JSON</strong> 接口，供站点或 App 使用（列表默认不含 <code>body</code>，避免大包）。</li></ul><h3 id="_1-3-非功能与约束" tabindex="-1">1.3 非功能与约束 <a class="header-anchor" href="#_1-3-非功能与约束" aria-label="Permalink to &quot;1.3 非功能与约束&quot;">​</a></h3><ul><li><strong>部署成本</strong>：尽量无独立服务器运维，适合 Serverless / 边缘部署。</li><li><strong>存储</strong>：与 Worker 同生态、SQL 易查、成本低；本项目选用 <strong>Cloudflare D1</strong>（SQLite）。</li><li><strong>合规</strong>：爬取与数据使用须遵守上游服务条款与适用法律；频率需可控，避免对上游造成不当压力（终端或调度侧可加间隔、限流）。</li></ul><hr><h2 id="二、实现" tabindex="-1">二、实现 <a class="header-anchor" href="#二、实现" aria-label="Permalink to &quot;二、实现&quot;">​</a></h2><h3 id="_2-1-技术选型" tabindex="-1">2.1 技术选型 <a class="header-anchor" href="#_2-1-技术选型" aria-label="Permalink to &quot;2.1 技术选型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>选择</th><th>说明</th></tr></thead><tbody><tr><td>运行时</td><td><strong>Cloudflare Workers</strong></td><td>边缘执行，与 <code>fetch</code>、定时/HTTP 触发天然契合；单文件入口 <code>src/index.ts</code> 导出 <code>fetch</code> 处理器。</td></tr><tr><td>数据库</td><td><strong>D1</strong></td><td>通过 <code>wrangler.toml</code> 绑定 <code>DB</code>；迁移放在 <code>migrations/</code>，用 Wrangler 在本地/远程应用。</td></tr><tr><td>语言</td><td><strong>TypeScript</strong></td><td>类型描述上游 JSON 与查询结果，便于维护。</td></tr></tbody></table><p>本项目<strong>不设独立 <code>build</code> 脚本</strong>：<code>wrangler dev</code> / <code>wrangler deploy</code> 时完成打包与 TS 处理。</p><h3 id="_2-2-数据模型-概要" tabindex="-1">2.2 数据模型（概要） <a class="header-anchor" href="#_2-2-数据模型-概要" aria-label="Permalink to &quot;2.2 数据模型（概要）&quot;">​</a></h3><ul><li><strong><code>articles</code></strong>：以上游文章 <code>id</code> 为主键，保存列表字段、详情字段（如 <code>body</code>、<code>category</code>）、原始详情 JSON（<code>result_json</code>），以及 <code>list_synced_at</code>、<code>detail_synced_at</code> 用于判断列表/详情是否已同步。</li><li><strong><code>crawl_meta</code></strong>：键值表，保存列表阶段的 <strong><code>list_next_page</code></strong>、<strong><code>list_max_page</code></strong>，实现列表游标持久化。</li></ul><p>详见 <code>migrations/0001_init.sql</code>、<code>migrations/0002_crawl_meta.sql</code>。</p><h3 id="_2-3-核心流程-两阶段同步" tabindex="-1">2.3 核心流程：两阶段同步 <a class="header-anchor" href="#_2-3-核心流程-两阶段同步" aria-label="Permalink to &quot;2.3 核心流程：两阶段同步&quot;">​</a></h3><ol><li><p><strong>阶段一（列表）</strong><br> 客户端反复请求 <strong><code>GET /crawl/sync-list?chunk=…</code></strong>（单次在 Worker 内最多处理若干列表页，避免超时）。首次从第 1 页解析上游总页数并写入 <code>crawl_meta</code>，之后按游标继续；列表内若出现重复 id，在写入前<strong>按 id 去重</strong>（后者覆盖前者）。直到返回 <strong><code>list_phase_done: true</code></strong>，表示列表页已按游标跑完。</p></li><li><p><strong>阶段二（详情）</strong><br> 反复请求 <strong><code>GET /crawl/sync-detail?limit=…</code></strong> 或 <strong><code>GET /pending?limit=…</code></strong>：从库中选出 <strong><code>detail_synced_at</code> 为空</strong>的记录，按 <strong><code>id</code> 升序</strong>取一批，逐条请求上游详情并 upsert。配合 <strong><code>GET /stats</code></strong> 观察 <strong><code>pendingDetail</code></strong>，直至为 0（或不再下降，需结合失败重试策略排查）。</p></li></ol><h3 id="_2-4-接口分层-思路" tabindex="-1">2.4 接口分层（思路） <a class="header-anchor" href="#_2-4-接口分层-思路" aria-label="Permalink to &quot;2.4 接口分层（思路）&quot;">​</a></h3><ul><li><strong>写库（爬取）</strong>：<code>/crawl/sync-list</code>、<code>/crawl/sync-detail</code>、<code>/pending</code> 等，负责与上游通信并写 D1。</li><li><strong>读库（应用）</strong>：<code>/api/list</code>、<code>/api/detail</code>，仅从 D1 读取，支持分页与「仅已同步详情」等查询。</li><li><strong>统计</strong>：<code>/stats</code> 汇总条数、列表阶段是否完成、待补详情数量等。</li></ul><p>调试辅助路由（如单页列表、固定区间列表、单篇详情拉取）便于排障，生产调度以两阶段主路径为主。</p><h3 id="_2-5-部署与数据库迁移注意" tabindex="-1">2.5 部署与数据库迁移注意 <a class="header-anchor" href="#_2-5-部署与数据库迁移注意" aria-label="Permalink to &quot;2.5 部署与数据库迁移注意&quot;">​</a></h3><ul><li>Worker 通过 <strong><code>npm run deploy</code></strong>（即 <code>wrangler deploy</code>）发布；首次需 <strong><code>npx wrangler login</code></strong>。</li><li><strong>Git 自动部署通常只发代码</strong>，不会自动执行 D1 迁移；<strong>新增或修改 <code>migrations/*.sql</code> 后</strong>，需在可信环境执行远程迁移（见 <a href="./使用说明">使用说明.md</a>）。</li><li><code>wrangler.toml</code> 中的 <strong><code>database_id</code></strong> 必须与 Cloudflare 控制台中的 D1 实例一致。</li></ul><hr><h2 id="三、总结" tabindex="-1">三、总结 <a class="header-anchor" href="#三、总结" aria-label="Permalink to &quot;三、总结&quot;">​</a></h2><h3 id="_3-1-做得好的地方" tabindex="-1">3.1 做得好的地方 <a class="header-anchor" href="#_3-1-做得好的地方" aria-label="Permalink to &quot;3.1 做得好的地方&quot;">​</a></h3><ul><li><strong>问题拆分清晰</strong>：列表与详情分两阶段，配合游标与 <code>detail_synced_at</code>，兼顾 Worker 时限与可恢复进度。</li><li><strong>结构简单</strong>：单 Worker 单入口，读写路由集中，依赖少，适合小团队或个人维护。</li><li><strong>读侧接口明确</strong>：分页列表与单篇详情分离，列表默认不带正文，有利于列表页性能。</li></ul><h3 id="_3-2-局限与可改进方向-备忘" tabindex="-1">3.2 局限与可改进方向（备忘） <a class="header-anchor" href="#_3-2-局限与可改进方向-备忘" aria-label="Permalink to &quot;3.2 局限与可改进方向（备忘）&quot;">​</a></h3><ul><li><strong>安全</strong>：若 Worker 公网可访问，爬取类接口缺少鉴权时可能被滥用；生产环境建议加 <strong>Secret、Cloudflare Access 或限流</strong>。</li><li><strong>健壮性</strong>：对上游 HTTP 状态码、失败重试、列表页失败是否跳过等策略可按业务收紧（避免静默丢页）。</li><li><strong>性能</strong>：详情批量拉取当前偏串行，在子请求配额内可引入<strong>有限并发</strong>与 <strong>D1 batch 写入</strong>以缩短单次请求耗时。</li></ul><h3 id="_3-3-一句话概括" tabindex="-1">3.3 一句话概括 <a class="header-anchor" href="#_3-3-一句话概括" aria-label="Permalink to &quot;3.3 一句话概括&quot;">​</a></h3><p>这是一个 <strong>Cloudflare Workers + D1</strong> 的小型同步服务：把上游新闻<strong>先全列表、后补详情</strong>写入 SQLite，再对外提供<strong>稳定的只读 JSON API</strong>；实现上强调<strong>游标断点与两阶段分工</strong>，部署上记住<strong>代码与 D1 迁移分离发布</strong>。</p>',32)])])}const _=e(d,[["render",n]]);export{u as __pageData,_ as default};
